s=s[:old_start]+'''function drawMain(changed) {
  // what Streamlit can really do (tested Nov 2026): a chart is swapped, not morphed, so a quick
  // 150 ms crossfade plus a shimmer marks the change, only when the settings changed
  const [tr, lay] = mainTraces(), box = document.getElementById("mainbox");
  delete lay.transition;
  if (changed && !still()) {
    box.style.transition = "opacity 150ms cubic-bezier(.2,.8,.2,1)"; box.style.opacity = .35;
    setTimeout(() => { Plotly.react("c_main", tr, lay, CFG); box.style.opacity = 1;
      box.classList.remove("loading"); void box.offsetWidth; box.classList.add("loading"); }, 150);
  } else Plotly.react("c_main", tr, lay, CFG);
'''+s[old_end:]
