input.content:
/* ---------- v3: one page at a time, with a quick page change ---------- */
.page { display:none; }
.page.show { display:block; animation:pagein 240ms var(--snap); }
@keyframes pagein { from { opacity:0; transform:translateY(8px) } to { opacity:1; transform:none } }
.page > section:last-child { border-bottom:0; }
.eyebrow { font:700 12px 'JetBrains Mono', monospace; color:var(--accent); letter-spacing:.12em; }
.hero { display:grid; grid-template-columns:1.05fr 1fr; gap:28px; align-items:center; }
.crowd { border:1px solid var(--line); background:var(--card); position:relative; }
.crowd canvas { display:block; width:100%; height:auto; }
.crowd .legend { display:flex; flex-wrap:wrap; gap:6px 16px; padding:8px 12px; border-top:1px solid var(--line);
                 font:13px 'JetBrains Mono', monospace; color:var(--text2); }
.crowd .legend i { display:inline-block; width:10px; height:10px; border-radius:50%; margin-right:6px; vertical-align:-1px; }
.crowd .ctl { position:absolute; top:8px; right:8px; display:flex; gap:6px; }
.crowd .ctl button { min-height:32px; padding:0 10px; font-size:12px; background:rgba(0,0,0,.6); }
.steps3 { display:grid; grid-template-columns:repeat(3,1fr); gap:12px; margin:16px 0; }
.step { border:1px solid var(--line); background:var(--card); padding:14px 16px; transition:transform var(--fast) var(--snap), border-color var(--fast); }
.step:hover { transform:translateY(-2px); border-color:var(--accent); }
.step .k { font:700 12px 'JetBrains Mono', monospace; color:var(--accent); letter-spacing:.08em; }
.step b { color:var(--text); display:block; margin:4px 0; font-size:16px; }
.step svg { display:block; width:100%; height:86px; margin:6px 0 4px; }
.quote-big { border-left:3px solid var(--accent); padding:6px 16px; margin:18px 0; font-size:19px; color:var(--text); max-width:820px; }
.edu { border:1px solid var(--accent); background:var(--accent-dim); color:var(--text); padding:14px 16px; margin:14px 0 6px;
       font:600 15px 'JetBrains Mono', monospace; letter-spacing:.02em; }
.edu b { color:var(--accent); }
.refs { list-style:none; padding:0; margin:0; counter-reset:r; }
.refs li { counter-increment:r; padding:12px 0 12px 46px; border-top:1px solid var(--line); position:relative; font-size:15px; }
.refs li::before { content:"[" counter(r) "]"; position:absolute; left:0; top:12px; font:600 13px 'JetBrains Mono', monospace; color:var(--accent); }
.refs li .use { display:block; color:var(--muted); font-size:14px; margin-top:2px; }
.refs li a { word-break:break-word; }
.refgrid { display:grid; grid-template-columns:1fr 1fr; gap:10px 32px; }
.pill2 { display:inline-block; font:600 11px 'JetBrains Mono', monospace; border:1px solid var(--line2); color:var(--muted); padding:1px 7px; margin-right:6px; }
@media (max-width:900px) { .hero, .steps3, .refgrid { grid-template-columns:1fr; } }

