/* ---------- v3: pages ---------- */
const PAGES = ["start", "story", "lab", "checks", "sources"];
function route() {
  const id = (location.hash || "#start").slice(1), p = PAGES.includes(id) ? id : "start";
  document.querySelectorAll(".page").forEach(el => el.classList.toggle("show", el.id === "p-" + p));
  document.querySelectorAll("nav a").forEach(a => a.classList.toggle("on", a.getAttribute("href") === "#" + p));
  ink(); window.scrollTo({top:0, behavior:"instant"});
  requestAnimationFrame(() => {                       // charts drawn while hidden need their real width now
    if (p === "story") Plotly.Plots.resize("c_kirman");
    if (p === "lab") Plotly.Plots.resize("c_main");
    document.querySelectorAll("#p-" + p + " .rise").forEach(el => el.classList.add("in"));
  });
}
addEventListener("hashchange", route);
document.querySelectorAll("[data-go]").forEach(b => b.onclick = () => location.hash = "#" + b.dataset.go);

/* ---------- v3: the trader crowd, from the model's biggest-crash run ---------- */
const crowd = (() => {
  const cv = document.getElementById("crowd"), ctx = cv.getContext("2d"), W = cv.width, H = cv.height, N = 500;
  const c = M.crash, days = c.day.length;
