/* ---------- the Story: one idea per screen ---------- */
.story { display:grid; grid-template-columns:250px 1fr; gap:22px; align-items:start; }
.stepper { list-style:none; margin:0; padding:0; position:sticky; top:118px; border-left:1px solid var(--line); }
.stepper li { position:relative; padding:9px 10px 9px 30px; cursor:pointer; font-size:14px; color:var(--muted); min-height:44px;
              transition:color var(--fast) var(--snap), background var(--fast); }
.stepper li:hover { color:var(--text); background:#0B0B0B; }
.stepper li::before { content:attr(data-n); position:absolute; left:-12px; top:10px; width:22px; height:22px; display:grid; place-items:center;
                      font:700 11px 'JetBrains Mono', monospace; background:var(--bg); border:1px solid var(--line2); color:var(--muted);
                      transition:all var(--med) var(--snap); }
.stepper li.done::before { content:"✓"; color:var(--up); border-color:var(--up); }
.stepper li.on { color:var(--text); }
.stepper li.on::before { background:var(--accent); border-color:var(--accent); color:#000; transform:scale(1.1); }
.stepcard { border:1px solid var(--line); background:var(--card); padding:18px 20px 16px; min-width:0; }
.progress { height:3px; background:var(--line); margin:-18px -20px 16px; }
.progress span { display:block; height:100%; background:var(--accent); width:0; transition:width var(--med) var(--snap); box-shadow:0 0 10px var(--accent); }
.s-title { font:700 24px/1.25 'JetBrains Mono', monospace; color:var(--text); margin:6px 0 14px; }
.s-title::before { content:none; }
.s-grid { display:grid; grid-template-columns:1fr 1.35fr; gap:22px; align-items:start; }
.s-grid > * { min-width:0; }
.s-body p { margin:0 0 10px; font-size:16.5px; }
.s-body b { color:var(--text); }
.bignum { margin:14px 0; font:700 40px 'JetBrains Mono', monospace; color:var(--accent); line-height:1.05; }
.bignum small { display:block; font:500 13px 'JetBrains Mono', monospace; color:var(--muted); margin-top:4px; letter-spacing:.02em; }
.notice { border-left:3px solid var(--herd); background:rgba(242,167,218,.07); padding:9px 12px; font-size:15px; }
.notice::before { content:"WHAT TO NOTICE ▸ "; font:700 12px 'JetBrains Mono', monospace; color:var(--herd); letter-spacing:.05em; }
.s-vis { min-height:330px; }
.s-swap { animation:swap 220ms var(--snap); }
@keyframes swap { from { opacity:0; transform:translateX(10px) } to { opacity:1; transform:none } }
.s-nav { display:flex; justify-content:space-between; align-items:center; gap:10px; margin-top:16px; border-top:1px solid var(--line); padding-top:12px; }
.kinds { display:grid; gap:10px; padding:14px; }
.kind { display:grid; grid-template-columns:120px 1fr; gap:12px; align-items:center; border:1px solid var(--line); padding:10px 12px; }
.kind svg { width:120px; height:46px; }
.kind b { color:var(--text); display:block; }
.guess { display:flex; flex-wrap:wrap; gap:6px; margin:10px 0; }
.verdict { list-style:none; padding:14px; margin:0; display:grid; gap:8px; }
.verdict li { border:1px solid var(--line); padding:10px 12px; font-size:15px; display:grid; grid-template-columns:28px 1fr; gap:8px; }
.verdict li b { color:var(--text); }
@media (max-width:900px) { .story, .s-grid { grid-template-columns:1fr; } .stepper { position:static; display:flex; overflow-x:auto; border-left:0; border-bottom:1px solid var(--line); }
  .stepper li { white-space:nowrap; padding:10px 10px 10px 30px; } .stepper li::before { left:4px; } .stepper li span { display:none; } }

