/* ---------- the Story: eight steps, one idea each ---------- */
const story = (() => {
  const c = M.crash_years, fit = M.runs[String(M.fit_a1)];
  const tailLayout = (extra) => { const l = base(Object.assign({ height:330, margin:{l:56, r:10, t:10, b:44} }, extra || {}));
    Object.assign(l.xaxis, { type:"log", title:{text:"Size of the day's move (standard deviations)"}, tickvals:[0.1,0.5,1,2,5,10,20], ticktext:["0.1","0.5","1","2","5","10","20"] });
    Object.assign(l.yaxis, { type:"log", range:[-5, 0], dtick:1, tickformat:".3~%", title:{text:"Share of days at least this big"} });
    l.legend = { x:0.02, y:0.05, bgcolor:"rgba(0,0,0,.6)", font:{size:12} }; return l; };
  const bell = { x:M.bell.x, y:M.bell.y, mode:"lines", line:{color:P.bell, width:2.5, dash:"dot"}, name:"Bell curve" };
  const spx = { x:M.tail_spx.x, y:M.tail_spx.y, mode:"lines", line:{color:P.real, width:3}, name:"Real S&P 500" };
  const four = { type:"line", x0:4, x1:4, yref:"paper", y0:0, y1:1, line:{color:P.guide, width:1.5, dash:"dot"} };
  const plot = (tr, lay) => Plotly.react("s-vis", tr, lay, CFG);
  const html = h => { Plotly.purge("s-vis"); document.getElementById("s-vis").innerHTML = h; };
  let guess = null;
  const STEPS = [
    { short:"The puzzle", title:"Real markets have days a bell curve says should never happen",
      body:`<p>Measure each day's move in <b>standard deviations</b> (sd): the size of a typical day. A 4-sd day is four typical days at once.</p>
            <p>If daily moves followed a <b>bell curve</b>, days that big would almost never come. The real S&amp;P 500 has had dozens.</p>`,
      num:() => `${M.spx.big} days`, numl:() => `beyond 4 sd since 1950 · a bell curve expects ${fmt(M.spx.bell_big, 1)}`,
      notice:"Right of the dotted 4: the bell curve falls off a cliff. The real market's white line keeps going.",
      cap:"Each step down the side is 10 times rarer. Up = common, down = rare.",
      draw:() => plot([bell, spx], tailLayout({ shapes:[four] })) },
    { short:"The idea", title:"The idea: traders copy each other, like ants do",
      body:`<p>Economist Alan Kirman watched ants choose between two identical food sources. They don't split evenly: they <b>crowd onto one</b>, then suddenly switch together.</p>
            <p>Each ant mostly copies another ant. The same rule, copying the crowd, is the "herding" this project puts into a market.</p>`,
      num:() => M.kirman.tv.toFixed(3), numl:() => "gap between our ant simulation and Kirman's exact math (0 = perfect; must be under 0.05)",
      notice:"The line jumps from top to bottom: nearly all ants switch sources together. Nobody tells them to.",
      cap:"100 ants over 5 million steps: how many are at source A.",
      draw:() => plot([{ x:M.kirman.steps, y:M.kirman.count, mode:"lines", line:{color:P.herd, width:1.6}, name:"Ants at A" }],
        (() => { const l = base({ height:330, margin:{l:56, r:10, t:10, b:44}, showlegend:false }); l.xaxis.title = {text:"Steps (millions)"}; l.yaxis.title = {text:"Ants at source A"}; return l; })()) },
    { short:"The market", title:"So we build a market of 500 traders, fed only calm news",
      body:`<p>Every trader is one of three kinds, and switches to whichever kind is making more money.</p>
            <p>The <b>news</b> (changes in what the stock is really worth) is plain bell-curve noise. So if big days appear, the <b>traders</b> made them.</p>`,
      num:() => "500", numl:() => "simulated traders, every day for 77 years",
      notice:"Only one kind copies the crowd: the trend chasers. Turning that copying up or down is the experiment.",
      cap:"The three kinds of trader (Lux & Marchesi, 1999).",
      draw:() => html(`<div class="kinds">
        <div class="kind"><svg viewBox="0 0 120 46">${[...Array(18).keys()].map(i => `<circle cx="${8 + (i % 9) * 13}" cy="${12 + Math.floor(i / 9) * 18}" r="4.5" fill="${P.fund}"/>`).join("")}</svg>
          <div><b>Value traders</b>Buy when the price is below what the stock is worth, sell when it is above. They pull the price back.</div></div>
        <div class="kind"><svg viewBox="0 0 120 46">${[...Array(18).keys()].map(i => `<circle cx="${8 + (i % 9) * 13}" cy="${12 + Math.floor(i / 9) * 18}" r="4.5" fill="${P.up}"/>`).join("")}</svg>
          <div><b>Optimists</b>Trend chasers who think it will rise: they buy. They copy the crowd's mood.</div></div>
        <div class="kind"><svg viewBox="0 0 120 46">${[...Array(18).keys()].map(i => `<circle cx="${8 + (i % 9) * 13}" cy="${12 + Math.floor(i / 9) * 18}" r="4.5" fill="${P.down}"/>`).join("")}</svg>
          <div><b>Pessimists</b>Trend chasers who think it will fall: they sell. They copy the crowd's mood too.</div></div></div>`) },
    { short:"Test 1", title:"Test 1: with only value traders, the market is a calm bell curve",
      body:`<p>Switch the trend chasers off. Only value traders remain, reacting to bell-curve news.</p>
            <p>The market's daily moves come out as a bell curve too: <b>no extra big days</b>. So the news alone does not make crashes.</p>`,
      num:() => `${M.fund.big} days`, numl:() => `beyond 4 sd in 77 simulated years · the real market had ${M.spx.big}`,
      notice:"The blue line sits right on top of the dotted bell curve.",
      cap:"Value traders only, against a bell curve.",
      draw:() => plot([bell, { x:M.tail_fund.x, y:M.tail_fund.y, mode:"lines", line:{color:P.fund, width:3, dash:"dashdot"}, name:"Value traders only" }], tailLayout({ shapes:[four] })) },
    { short:"Test 2", title:"Test 2: trend chasers who don't copy each other make the market run away",
      body:`<p>Add trend chasers, but don't let them copy each other. Buying after a rise brings more buying.</p>
            <p>The price stays calm for years, then <b>leaves its true value and never comes back</b>: a bubble that never ends. Real markets don't do that.</p>`,
      num:() => `${M.runaway_count[0]} of ${M.runaway_count[1]}`, numl:() => "simulated histories ran away",
      notice:() => `Calm for about ${M.runaway.calm.toLocaleString()} days while trend chasers slowly grow, then a vertical take-off.`,
      cap:"Top: share of traders chasing the trend. Bottom: how far the price is above its true value.",
      draw:() => { const R = M.runaway, b = base();
        plot([{ x:R.day, y:R.z, mode:"lines", line:{color:"#E66A1F", width:2}, name:"Trend chasers" },
              { x:R.day, y:R.gap, mode:"lines", line:{color:P.real, width:1.8}, name:"Price above value", yaxis:"y2" }],
          base({ height:330, margin:{l:56, r:10, t:10, b:44}, showlegend:false,
            yaxis:{...b.yaxis, domain:[.55, 1], tickformat:".0%", range:[0, 1], title:{text:"Chasers"}},
            yaxis2:{...b.yaxis, domain:[0, .45], tickformat:"+.0%", title:{text:"Mispricing"}, anchor:"x"},
            xaxis:{...b.xaxis, anchor:"y2", title:{text:"Trading day"}} })); } },
    { short:"Test 3", title:"Test 3: trend chasers who copy each other give the real market's fat tails",
      body:`<p>Now let trend chasers copy the crowd's mood. Optimism spreads, then collapses all at once, and the value traders pull the price back.</p>
            <p>Big days now come about as often as in the real S&amp;P 500, and in <b>bursts</b>, like the real thing.</p>`,
      num:() => fmt(M.checks.tail_median), numl:() => `tail exponent of the model (median of 40 runs) · real S&P 500: ${fmt(M.spx.tail)} · a bell curve: about 6`,
      notice:"The pink herding line follows the white S&P line far past 4 sd. The bell curve gave up long before.",
      cap:"Copying trend chasers (pink) against the real market (white).",
      draw:() => plot([bell, spx, { x:fit.tail_x, y:fit.tail_y, mode:"lines", line:{color:P.herd, width:3}, name:"Herding model" }], tailLayout({ shapes:[four] })) },
    { short:"How much?", title:"How much copying? Guess first",
      body:() => `<p>If trend chasers copy each other more and more, does the market get <b>wilder</b> or <b>calmer</b>?</p>
            <div class="guess">${["Wilder", "Wilder, then calmer", "Calmer"].map(g => `<button class="${guess === g ? "primary" : ""}" data-g="${g}">${g}</button>`).join("")}</div>
            ${guess ? `<p>${guess === "Calmer" ? "<b>Right, surprisingly.</b>" : "<b>Not quite.</b>"} Too little copying and the market runs away; more copying calms it down. The real market's tails show up only near the edge between the two.</p>` : `<p class="cap">The chart appears once you guess.</p>`}`,
      num:() => guess ? String(M.fit_a1) : "?", numl:() => guess ? "the herding strength that matches the S&P 500: right at the edge" : "make a guess",
      notice:"Lux and Marchesi called their paper “Scaling and criticality”: fat tails appear near a tipping point.",
      cap:"Each dot: the tail exponent at one herding strength (10 runs each). Bars: how many runs ran away.",
      draw:() => { if (!guess) { html(`<div style="display:grid;place-items:center;height:330px;color:var(--muted)" class="mono">◌ hidden until you guess</div>`); return; }
        const S = M.sweep, ok = S.filter(s => s.tail !== null && s.ran_away <= s.n / 2), b = base();
        plot([{ x:S.map(s => s.a1), y:S.map(s => s.ran_away), type:"bar", marker:{color:"rgba(255,122,107,.35)"}, name:"Ran away (of 10)", yaxis:"y2" },
              { x:ok.map(s => s.a1), y:ok.map(s => s.tail), mode:"lines+markers", line:{color:P.herd, width:3}, marker:{size:8}, name:"Tail exponent" }],
          base({ height:330, margin:{l:56, r:56, t:10, b:44}, legend:{x:.02, y:.98, font:{size:12}},
            shapes:[{ type:"line", xref:"paper", x0:0, x1:1, y0:M.spx.tail, y1:M.spx.tail, line:{color:P.real, width:1.5, dash:"dash"} }],
            annotations:[{ xref:"paper", x:.99, y:M.spx.tail, text:"real S&P", showarrow:false, xanchor:"right", yanchor:"bottom", font:{color:P.real, size:12} }],
            xaxis:{...b.xaxis, title:{text:"Herding strength (how strongly trend chasers copy)"}},
            yaxis:{...b.yaxis, title:{text:"Tail exponent (higher = calmer)"}},
            yaxis2:{...b.yaxis, overlaying:"y", side:"right", range:[0, 30], showgrid:false, title:{text:"Ran away"}} })); } },
    { short:"The verdict", title:"The verdict: herding explains a lot, not everything",
      body:`<p>Fed only calm news, a market of copying traders reproduces most of what makes real markets wild. Two things it still misses.</p>`,
      num:() => `${fmt(c.model8, 0)} yrs`, numl:() => "between 8-sd crashes in the model · a bell curve: trillions of years",
      notice:"Every number here is checked on the Checks page, with the rule for each test.",
      cap:"What herding alone explains, and what it doesn't.",
      draw:() => html(`<ul class="verdict">
        <li><span class="ok">✓</span><span><b>Fat tails.</b> Big days as common as in the real S&amp;P 500 (tail ${fmt(M.checks.tail_median)} vs ${fmt(M.spx.tail)}).</span></li>
        <li><span class="ok">✓</span><span><b>Wild days in bursts</b>, like real markets.</span></li>
        <li><span class="ok">✓</span><span><b>Crashes within decades:</b> an 8-sd fall about every ${fmt(c.model8, 0)} years, not trillions.</span></li>
        <li><span class="mid">≈</span><span><b>Black Monday's size</b> comes about every ${fmt(c.bm_model, 0)} years in the model; the real market had one in ${fmt(c.spx_years, 0)}.</span></li>
        <li><span style="color:var(--down)">✗</span><span><b>Falls bigger than rises.</b> Real crashes are bigger than real rallies; the model's are mirror images.</span></li>
        <li style="border-color:var(--accent)"><span>▶</span><span><a href="#lab">Try it yourself in the Test program</a> · <a href="#checks">See every check</a></span></li></ul>`) },
  ];
  let i = 0;
  const val = v => typeof v === "function" ? v() : v;
  function show(n, dir) {
    i = Math.max(0, Math.min(STEPS.length - 1, n));
    const s = STEPS[i];
    document.getElementById("stepper").innerHTML = STEPS.map((t, j) =>
      `<li data-n="${j + 1}" class="${j === i ? "on" : j < i ? "done" : ""}" data-i="${j}"><span>${t.short}</span></li>`).join("");
    document.querySelectorAll("#stepper li").forEach(li => li.onclick = () => show(+li.dataset.i));
    document.getElementById("sbar").style.width = ((i + 1) / STEPS.length * 100) + "%";
    document.getElementById("s-of").textContent = `STEP ${i + 1} OF ${STEPS.length}`;
    document.getElementById("s-title").textContent = s.title;
    document.getElementById("s-body").innerHTML = val(s.body);
    document.getElementById("s-num").textContent = val(s.num);
    document.getElementById("s-numl").textContent = val(s.numl);
    document.getElementById("s-notice").textContent = val(s.notice);
    document.getElementById("s-cap").textContent = s.cap;
    document.querySelectorAll("#s-body [data-g]").forEach(b => b.onclick = () => { guess = b.dataset.g; show(i); });
    const vis = document.getElementById("s-vis"); s.draw();
    if (!still()) [vis, document.getElementById("s-title")].forEach(el => { el.classList.remove("s-swap"); void el.offsetWidth; el.classList.add("s-swap"); });
    document.getElementById("s-back").disabled = i === 0;
    const next = document.getElementById("s-next");
    next.textContent = i === STEPS.length - 1 ? "Try it yourself →" : "Next →";
  }
  document.getElementById("s-back").onclick = () => show(i - 1);
  document.getElementById("s-next").onclick = () => i === STEPS.length - 1 ? (location.hash = "#lab") : show(i + 1);
  addEventListener("keydown", e => { if (!document.getElementById("p-story").classList.contains("show") || /INPUT/.test(document.activeElement.tagName)) return;
    if (e.key === "ArrowRight") show(i + 1); if (e.key === "ArrowLeft") show(i - 1); });
  show(0);
  return { show, resize: () => document.querySelector("#s-vis .js-plotly-plot") && Plotly.Plots.resize("s-vis") };
})();

