        (() => { const l = base({ height:330, margin:{l:56, r:10, t:10, b:44}, showlegend:false }); l.xaxis.title = {text:"Steps (millions)"}; l.yaxis.title = {text:"Ants at source A"}; return l; })()) },
    { short:"The market", title:"So we build a market of 500 traders, fed only calm news",
      body:`<p>Every trader is one of three kinds, and switches to whichever kind is making more money.</p>
            <p>The <b>news</b> (changes in what the stock is really worth) is plain bell-curve noise. So if big days appear, the <b>traders</b> made them.</p>`,
