    document.getElementById("stepper").innerHTML = STEPS.map((t, j) =>
      `<li data-n="${j + 1}" class="${j === i ? "on" : j < i ? "done" : ""}" data-i="${j}"><span>${t.short}</span></li>`).join("");
    document.querySelectorAll("#stepper li").forEach(li => li.onclick = () => show(+li.dataset.i));
    document.getElementById("sbar").style.width = ((i + 1) / STEPS.length * 100) + "%";
    document.getElementById("s-of").textContent = `STEP ${i + 1} OF ${STEPS.length}`;
    document.getElementById("s-title").textContent = s.title;
    document.getElementById("s-body").innerHTML = val(s.body);
    document.getElementById("s-num").textContent = val(s.num);
    document.getElementById("s-numl").textContent = val(s.numl);
    document.getElementById("s-notice").textContent = val(s.notice);
    document.getElementById("s-cap").textContent = s.cap;
    document.querySelectorAll("#s-body [data-g]").forEach(b => b.onclick = () => { guess = b.dataset.g; show(i); });
    const vis = document.getElementById("s-vis"); s.draw();
    if (!still()) [vis, document.getElementById("s-title")].forEach(el => { el.classList.remove("s-swap"); void el.offsetWidth; el.classList.add("s-swap"); });
    document.getElementById("s-back").disabled = i === 0;
    const next = document.getElementById("s-next");
    next.textContent = i === STEPS.length - 1 ? "Try it yourself →" : "Next →";
  }
  document.getElementById("s-back").onclick = () => show(i - 1);
  document.getElementById("s-next").onclick = () => i === STEPS.length - 1 ? (location.hash = "#lab") : show(i + 1);
  addEventListener("keydown", e => { if (!document.getElementById("p-story").classList.contains("show") || /INPUT/.test(document.activeElement.tagName)) return;
    if (e.key === "ArrowRight") show(i + 1); if (e.key === "ArrowLeft") show(i - 1); });
  show(0);
  return { show, resize: () => document.querySelector("#s-vis .js-plotly-plot") && Plotly.Plots.resize("s-vis") };
})();

