.tasks ol { list-style:none; padding:6px 14px 12px; margin:0; display:grid; gap:6px; }
.tasks li { display:grid; grid-template-columns:24px 1fr; gap:8px; font-size:15px; padding:6px 0; }
.tasks li .box { width:20px; height:20px; border:1px solid var(--line2); display:grid; place-items:center; font-size:13px; transition:all var(--med) var(--snap); }
.tasks li.done .box { background:var(--up); border-color:var(--up); color:#000; }
.tasks li.done .t { color:var(--muted); text-decoration:line-through; }
.srcnote { font-size:12px; color:var(--muted); }
.subrow { min-height:0; display:flex; flex-wrap:wrap; gap:8px; margin:-2px 0 8px; }
.subrow .seg { margin:0; }
.subrow .seg button { min-height:34px; font-size:12px; }
.insight { font-size:15px; color:var(--text2); border-top:1px dashed var(--line); padding-top:8px; margin-top:10px; }
.insight::before { content:"IN ONE LINE ▸ "; font:700 12px 'JetBrains Mono', monospace; color:var(--muted); letter-spacing:.05em; }
.presets { display:grid; grid-template-columns:repeat(3,1fr); gap:6px; margin-bottom:10px; }
.presets button { min-height:52px; padding:4px 6px; font-size:12px; line-height:1.25; display:flex; flex-direction:column; align-items:center; justify-content:center; }
.presets button small { font:500 11px Inter, sans-serif; color:inherit; opacity:.8; }
.presets button.on { background:var(--accent); color:#000; border-color:var(--accent); }
.lowbox { border:1px solid var(--line); background:var(--card); padding:12px; min-height:120px; }
.lowbox table td.num, .lowbox table th.num { text-align:right; font-family:'JetBrains Mono', monospace; }
.bd-list { max-height:320px; overflow:auto; }
.bd-list tr { cursor:pointer; } .bd-list tr.sel td { background:var(--accent-dim); }
.story-box { border-left:3px solid var(--accent); padding:10px 12px; margin-top:10px; background:var(--panel); font-size:15px; }
.checkrow { cursor:pointer; } .checkrow td:first-child::before { content:"▸ "; color:var(--accent); display:inline-block; transition:transform var(--fast) var(--snap); }
.checkrow.open td:first-child::before { transform:rotate(90deg); }
.detail td { background:#070707; padding:14px; }
.detail .grid2 { grid-template-columns:1fr 1.6fr; }
.mapchips { display:flex; gap:6px; flex-wrap:wrap; margin:6px 0; }
.mapchips button { min-height:34px; font-size:12px; } .mapchips button.on { border-color:var(--accent); color:var(--text); background:var(--accent-dim); }
.gallery img { width:100%; border:1px solid var(--line); background:#fff; display:block; }
.gallery figure { margin:0 0 18px; } .gallery figcaption { font-size:14px; color:var(--text2); margin-top:6px; }
.glossary dl { display:grid; grid-template-columns:200px 1fr; gap:8px 18px; margin:10px 0; font-size:15px; }
.glossary dt { font:600 14px 'JetBrains Mono', monospace; color:var(--text); }
@media (max-width:760px) { .glossary dl { grid-template-columns:1fr; } .detail .grid2 { grid-template-columns:1fr; } }

