input.content:
/* ---------- Test program: every view, sub-view and tab of today's site ---------- */
const X = window.MORE;
const VIEWS = ["Price", "Watch a crash", "How rare big days are", "Wild-day bursts"];
const SUBS = { "How rare big days are": ["Tail", "Histogram"], "Wild-day bursts": ["Bursts", "Memory"] };
let view = "Price", sub = { "How rare big days are":"Tail", "Wild-day bursts":"Bursts" }, mix = "Herding", zoom = "Biggest crash", range = "All";
const RANGES = ["1D", "7D", "YTD", "1Y", "5Y", "20Y", "All"];
const TRY = {
  "Price": "Click All and count the triangles. Each one is a day that moved more than 4 typical days at once.",
  "Watch a crash": "Look just before the fall in the middle panel: trend chasers pile in, the crowd leans one way, then it breaks.",
  "Tail": "Find 5 on the bottom axis. The bell curve has already dropped off the chart; the S&P 500 and the herding model are still there.",
  "Histogram": "Look past ±4 at the edges. The bell curve is flat at zero there; the real market's bars are not.",
  "Bursts": "Do the tall spikes come alone, or in clumps? Real market on top, model below, on the same scale.",
  "Memory": "Read the lines at 20 days. Above 0 means a wild day still predicts wild days a month later. The bell curve sits at 0." };
const CAP = {
  "Price": "The S&P 500, on a scale where equal steps up mean equal percentage gains. ▲ big rises, ▼ big falls. Lower panel: how far below its last high.",
  "Watch a crash": "The simulated market day by day. Top: price and the true value it is pulled back to. Middle: share of traders chasing the trend. Bottom: optimists minus pessimists.",
  "Tail": "Across: size of a day's move. Up: share of days at least that big. Both axes in steps of 10. A straight line means fat tails.",
  "Histogram": "How common each size of daily move is, in typical days. Up axis in steps of 10, so the rare edges still show.",
  "Bursts": "Each day's move, in typical days. Dotted lines: 4 typical days, which a bell curve almost never passes.",
  "Memory": "How much a wild day predicts wild days later, from 1 to 200 days apart. 0 means no memory." };
const cur = () => SUBS[view] ? sub[view] : view;
let runLog = [];

function rangeCut(xs) {
  if (range === "All" || range === "1D" || range === "7D") return 0;
  const end = new Date(xs[xs.length - 1]), start = new Date(end);
  if (range === "YTD") start.setMonth(0, 1); else start.setFullYear(end.getFullYear() - parseInt(range));
  const iso = start.toISOString().slice(0, 10);
  return xs.findIndex(x => x >= iso);
}
function mainTraces() {
  const run = M.runs[A1S[a1i]], b = base(), v = cur();
  if (v === "Price") {
    const k = rangeCut(M.price.x), kd = rangeCut(X.dd.x), from = M.price.x[k];
    const up = M.big.move.map(m => m > 0), inR = M.big.x.map(x => x >= from);
    const lay = base({ height:480, hovermode:"x unified",
      yaxis:{...b.yaxis, type:"log", domain:[.32, 1], title:{text:"Price"}}, yaxis2:{...b.yaxis, domain:[0, .25], tickformat:".0%", title:{text:"Below high"}, anchor:"x"},
      xaxis:{...b.xaxis, anchor:"y2"} });
    return [[{ x:M.price.x.slice(k), y:M.price.y.slice(k), mode:"lines", line:{color:P.real, width:2}, name:"S&P 500", hovertemplate:"%{y:,.2f}<extra></extra>" },
      { x:M.big.x.filter((_, i) => up[i] && inR[i]), y:M.big.y.filter((_, i) => up[i] && inR[i]), mode:"markers", name:"Big rise ▲", marker:{symbol:"triangle-up", size:10, color:P.up}, hoverinfo:"skip" },
      { x:M.big.x.filter((_, i) => !up[i] && inR[i]), y:M.big.y.filter((_, i) => !up[i] && inR[i]), mode:"markers", name:"Big fall ▼", marker:{symbol:"triangle-down", size:10, color:P.down}, hoverinfo:"skip" },
      { x:X.dd.x.slice(kd), y:X.dd.y.slice(kd), mode:"lines", fill:"tozeroy", fillcolor:"rgba(255,122,107,.12)", line:{color:P.down, width:1.4}, name:"Below last high", yaxis:"y2", hovertemplate:"%{y:.1%}<extra></extra>" }], lay];
  }
  if (v === "Watch a crash") {
    const src = mix === "Herding" ? (zoom === "Whole history" ? X.mm.herding_all : zoom === "Wildest year" ? X.mm.herding_burst : M.crash) : X.mm.fund_all;
    if (mix === "Trend chasers, no copying") {
      const R = M.runaway;
      return [[{ x:R.day, y:R.z, mode:"lines", line:{color:"#E66A1F", width:2}, name:"Trend chasers" },
               { x:R.day, y:R.gap, mode:"lines", line:{color:P.real, width:1.8}, name:"Price above true value", yaxis:"y2" }],
        base({ height:480, hovermode:"x unified", yaxis:{...b.yaxis, domain:[.55, 1], tickformat:".0%", range:[0, 1], title:{text:"Trend chasers"}},
          yaxis2:{...b.yaxis, domain:[0, .45], tickformat:"+.0%", title:{text:"Mispricing"}, anchor:"x"}, xaxis:{...b.xaxis, anchor:"y2", title:{text:"Simulated trading day"}},
          annotations:[{ x:R.gone, y:1, yref:"paper", text:"runs away", showarrow:false, font:{color:P.down, size:12}, xanchor:"right" }] })];
    }
    const col = mix === "Herding" ? P.herd : P.fund;
    const lay = base({ height:520, hovermode:"x unified",
      yaxis:{...b.yaxis, type:"log", domain:[.46, 1], title:{text:"Price"}, anchor:"x"}, yaxis2:{...b.yaxis, domain:[.24, .42], tickformat:".0%", range:[0, 1], title:{text:"Trend chasers"}, anchor:"x"},
      yaxis3:{...b.yaxis, domain:[0, .2], tickformat:"+.0%", title:{text:"Mood"}, anchor:"x"}, xaxis:{...b.xaxis, anchor:"y3", title:{text:"Simulated trading day"}} });
    return [[{ x:src.day, y:src.value, mode:"lines", line:{color:P.guide, width:1.6, dash:"dot"}, name:"True value" },
      { x:src.day, y:src.price, mode:"lines", line:{color:col, width:2}, name:"Price" },
      { x:src.day, y:src.z, mode:"lines", fill:"tozeroy", fillcolor:P.herdFill, line:{color:col, width:1.6}, name:"Trend chasers", yaxis:"y2" },
      { x:src.day, y:src.crowd, mode:"lines", line:{color:P.fund, width:1.6}, name:"Optimists − pessimists", yaxis:"y3" }], lay];
  }
  if (v === "Tail") {
    const lay = base({ height:470 });
    Object.assign(lay.xaxis, { type:"log", title:{text:"Size of the day's move (typical days)"}, tickvals:[0.1,0.2,0.5,1,2,5,10,20], ticktext:["0.1","0.2","0.5","1","2","5","10","20"] });
    Object.assign(lay.yaxis, { type:"log", range:[-5, 0], dtick:1, tickformat:".3~%", title:{text:"Share of days at least this big"} });
    const tr = [{ x:M.bell.x, y:M.bell.y, mode:"lines", line:{color:P.bell, width:2.5, dash:"dot"}, name:"Bell curve" },
      { x:M.tail_fund.x, y:M.tail_fund.y, mode:"lines", line:{color:P.fund, width:2.5, dash:"dashdot"}, name:"Value traders only" },
      { x:M.tail_spx.x, y:M.tail_spx.y, mode:"lines", line:{color:P.real, width:3}, name:"S&P 500" }];
    if (run.tail_x) tr.push({ x:run.tail_x, y:run.tail_y, mode:"lines", line:{color:P.herd, width:3}, name:"Herding model" });
    return [tr, lay];
  }
  if (v === "Histogram") {
    const lay = base({ height:470, bargap:0.05 }); lay.yaxis.type = "log"; lay.yaxis.dtick = 1; lay.yaxis.title = {text:"Share of days (per typical day)"};
    lay.xaxis.title = {text:"Size of the day's move (typical days)"}; lay.xaxis.range = [-8, 8];
    return [[{ x:X.hist.spx.x, y:X.hist.spx.y, type:"bar", marker:{color:"rgba(242,244,248,.55)"}, name:"S&P 500" },
      { x:X.hist.herd.x, y:X.hist.herd.y, mode:"lines+markers", line:{color:P.herd, width:2.5}, marker:{size:5}, name:"Herding model" },
      { x:X.bell_density.x, y:X.bell_density.y, mode:"lines", line:{color:P.bell, width:2.5, dash:"dot"}, name:"Bell curve" }], lay];
  }
  if (v === "Memory") {
    const lay = base({ height:470 }); lay.xaxis.type = "log"; lay.xaxis.title = {text:"Days apart"}; lay.yaxis.title = {text:"How much a wild day predicts a later one"};
    lay.xaxis.tickvals = X.memory.lags;
    return [[{ x:X.memory.lags, y:X.memory.spx, mode:"lines+markers", line:{color:P.real, width:3}, name:"S&P 500" },
      { x:X.memory.lags, y:X.memory.herd, mode:"lines+markers", line:{color:P.herd, width:3}, name:"Herding model" },
      { x:X.memory.lags, y:X.memory.fund, mode:"lines+markers", line:{color:P.fund, width:2.5, dash:"dashdot"}, name:"Value traders only" },
      { x:[1, 200], y:[0, 0], mode:"lines", line:{color:P.bell, width:2, dash:"dot"}, name:"Bell curve (no memory)" }], lay];
  }
  const shapes = [];
  for (const ax of ["y", "y2"]) for (const val of [-4, 4]) shapes.push({ type:"line", xref:(ax === "y" ? "x" : "x2") + " domain", x0:0, x1:1, yref:ax, y0:val, y1:val, line:{color:P.guide, width:1.5, dash:"dot"}, layer:"above" });
