const f2 = (v, d = 2) => v === null || v === undefined ? "—" : typeof v === "number" ? fmt(v, d) : v;
function lowtab(v) {
  low = v; const box = document.getElementById("lowbox");
  if (v === "Model vs market") {
    const T = X.table, names = { days:"Days", tail:"Tail exponent", kurtosis:"Excess kurtosis", memory:"Volatility memory", worst:"Worst day (typical days)",
      big_days:"Big days (over 4)", max_drawdown:"Worst drop from a high", runaway_day:"Ran away on day" };
    const idx = T.cols;
    box.innerHTML = `<table><tr><th>MEASURE</th>${T.rows.map(r => `<th class="num">${r[0].toUpperCase()}</th>`).join("")}</tr>` +
      idx.map((c, j) => `<tr><td>${names[c] || c}</td>${T.rows.map(r => `<td class="num">${c === "max_drawdown" && typeof r[j + 1] === "number" ? fmt(r[j + 1] * 100, 1) + "%" : c === "days" || c === "big_days" || c === "runaway_day" ? (r[j + 1] === null ? "—" : Math.round(r[j + 1]).toLocaleString()) : f2(r[j + 1])}</td>`).join("")}</tr>`).join("") + `</table>`;
  } else if (v === "Big days") {
    box.innerHTML = `<p class="cap" style="margin-top:0">${X.bigdays.length} days moved more than 4 typical days. Click one to read what happened.</p>
      <div class="bd-list"><table><tr><th>DATE</th><th class="num">MOVE</th><th class="num">TYPICAL DAYS</th></tr>${X.bigdays.map((d, i) =>
        `<tr data-i="${i}" class="${bdSel === i ? "sel" : ""}"><td class="mono">${d.date}</td><td class="num" style="color:${d.move > 0 ? P.up : P.down}">${d.move > 0 ? "▲ +" : "▼ −"}${fmt(Math.abs(d.move) * 100, 1)}%</td><td class="num">${d.sd > 0 ? "+" : "−"}${fmt(Math.abs(d.sd), 1)}</td></tr>`).join("")}</table></div>
      <div id="bd-story"></div>`;
    box.querySelectorAll("tr[data-i]").forEach(tr => tr.onclick = () => { bdSel = +tr.dataset.i; lowtab("Big days");
      const d = X.bigdays[bdSel]; document.getElementById("bd-story").innerHTML = `<div class="story-box">${d.story}${d.sources.length ? `<br><span class="cap">Sources: ${d.sources.map((s, k) => `<a href="${s}">[${k + 1}]</a>`).join(" ")}</span>` : ""}</div>`; });
  } else if (v === "Run log") {
    box.innerHTML = runLog.length ? `<table><tr><th>TIME</th><th class="num">HERDING</th><th class="num">TAIL</th><th class="num">KURTOSIS</th><th class="num">MEMORY</th></tr>${runLog.map(r =>
      `<tr><td class="mono">${r.t}</td><td class="num">${r.a1}</td><td class="num">${f2(r.tail)}</td><td class="num">${f2(r.kurt, 1)}</td><td class="num">${f2(r.memory)}</td></tr>`).join("")}</table>`
      : `<p class="cap">Move the herding slider: each run is added here.</p>`;
  } else {
    box.innerHTML = `<div id="c_dial"></div><p class="cap">The band: middle half of 10 saved runs at each strength (strengths where most ran away are left out). Dots: your runs.</p>`;
    const ok = X.band.filter(r => r.shown), bb = base();
    Plotly.newPlot("c_dial", [
      { x:ok.map(r => r.a1).concat(ok.map(r => r.a1).reverse()), y:ok.map(r => r.q3).concat(ok.map(r => r.q1).reverse()), fill:"toself", fillcolor:P.herdFill, line:{width:0}, hoverinfo:"skip", name:"Middle half of saved runs" },
      { x:ok.map(r => r.a1), y:ok.map(r => r.median), mode:"lines+markers", line:{color:P.herd, width:2.5}, name:"Saved runs (median)" },
      { x:runLog.map(r => r.a1), y:runLog.map(r => r.tail), mode:"markers", marker:{color:P.accent, size:11, line:{color:"#000", width:1}}, name:"Your runs" }],
      base({ height:320, shapes:[{ type:"line", xref:"paper", x0:0, x1:1, y0:M.spx.tail, y1:M.spx.tail, line:{color:P.real, width:1.5, dash:"dash"} }],
        xaxis:{...bb.xaxis, title:{text:"Herding strength"}}, yaxis:{...bb.yaxis, title:{text:"Tail exponent"}} }), CFG);
  }
  seg("lowtabs", LOWS, low, lowtab);
}

