function task(n) { if (n !== undefined) done[n] = true; const k = done.filter(Boolean).length;
  document.getElementById("task-n").textContent = `${k} of 3 done`; document.getElementById("task-bar").style.width = (k / 3 * 100) + "%";
  document.getElementById("task-list").innerHTML = TASKS.map((t, i) => `<li class="${done[i] ? "done" : ""}"><span class="box">${done[i] ? "✓" : ""}</span><span class="t">${t}</span></li>`).join(""); }
addEventListener("hashchange", () => { if (location.hash === "#checks") task(2); });

/* ---------- the tabs under the chart ---------- */
const LOWS = ["Model vs market", "Big days", "Run log", "Every run on one chart"];
let low = LOWS[0], bdSel = null;
const f2 = (v, d = 2) => v === null || v === undefined ? "—" : typeof v === "number" ? fmt(v, d) : v;
function lowtab(v) {
