/* ---------- Checks: the proposal's tests, beyond the paper, all markets, figures ---------- */
const CT = ["The proposal's tests", "Beyond the paper", "All markets", "Figures"];
let ct = CT[0], openRow = null, eps = "0.002", mapGroups = new Set(["Indexes", "Stocks", "Commodities"]), figSec = null;
const dots = (id, ys, band, ref, ytitle, color) => { const bb = base(), C = X.checks;
  const pts = C.seeds.map((s, i) => [s, ys[i]]).filter(p => p[1] !== null);
  const shapes = [{ type:"rect", xref:"paper", x0:0, x1:1, y0:band[0], y1:band[1], fillcolor:"rgba(52,211,153,.08)", line:{width:0}, layer:"below" }];
  if (ref !== null) shapes.push({ type:"line", xref:"paper", x0:0, x1:1, y0:ref, y1:ref, line:{color:P.real, width:1.5, dash:"dash"} });
  Plotly.newPlot(id, [{ x:pts.map(p => p[0]), y:pts.map(p => p[1]), mode:"markers", marker:{color, size:9}, name:"One history", hovertemplate:"history %{x}: %{y:.3f}<extra></extra>" }],
    base({ height:260, shapes, showlegend:false, xaxis:{...bb.xaxis, title:{text:"History number"}}, yaxis:{...bb.yaxis, title:{text:ytitle}} }), CFG); };
const DETAIL = {
  0: () => `<div class="grid2"><div><p>The herding rule comes from Kirman's ants. Each step one ant switches on its own (chance ε) or copies another.
      The simulation's share of time at each count must match Kirman's exact formula.</p>
      <p><b>Rule:</b> the gap between them is under 0.05 (0 = identical).</p>
      <label class="mono" style="font-size:13px">Chance an ant switches on its own (ε)</label><div class="seg" id="epsseg"></div>
      <p>Gap: <b class="mono" id="eps-tv"></b> · <span id="eps-v"></span></p></div><div class="chart" id="c_k"></div></div>`,
  1: () => `<div class="grid2"><div><p>With no trend chasers, the market should be as calm as its bell-curve news.</p>
      <p><b>Rule:</b> every history's excess kurtosis (0 for a bell curve) is within ±${fmt(X.checks.bell.tol, 3)} of 0: five times the
      wobble a perfect bell curve shows over this many days.</p><p>Farthest from 0: <b class="mono">${fmt(X.checks.bell.worst, 3)}</b> · <span class="ok">passes</span></p></div><div class="chart" id="c_1"></div></div>`,
  2: () => `<div class="grid2"><div><p>With herding, huge days should be about as common as in real markets.</p>
      <p><b>Rule:</b> the middle value of the tail exponents lies between 2.5 and 3.5. The "inverse cubic law" says about 3; the proposal guessed 2.6 to 3.</p>
      <p>Middle value <b class="mono">${fmt(M.checks.tail_median)}</b>, a little above the proposal's guess; the S&amp;P 500's ${fmt(M.spx.tail)} is inside it. <span class="ok">passes</span></p></div><div class="chart" id="c_2"></div></div>`,
  3: () => `<div class="grid2"><div><p>A bell curve says a Black-Monday-sized fall should come once in 10<sup>86</sup> years. Does herding bring crashes within decades?</p>
      <p><b>Rule:</b> (a) 8-typical-day falls come at least every 50 years: <b>${fmt(M.crash_years.model8, 0)} years</b> <span class="ok">passes</span>.
      (b) so do Black-Monday-sized falls: <b>${fmt(M.crash_years.bm_model, 0)} years</b> <span style="color:var(--down)">does not pass</span>.</p></div><div class="chart" id="c_3"></div></div>`,
  4: () => `<p>The model's extreme days and bunched wild days next to the S&amp;P 500's. No pass line: the proposal asked for "comparable".</p>
      <table><tr><th>MEASURE</th><th class="num">MODEL (MIDDLE VALUE)</th><th class="num">MIDDLE 90% OF HISTORIES</th><th class="num">S&amp;P 500</th></tr>${X.checks.table.map(r =>
      `<tr><td>${{ tail:"Tail exponent", kurtosis:"Excess kurtosis", memory:"Volatility memory (20 days)", worst:"Worst day (typical days)" }[r.index] || r.index}</td>
       <td class="num">${fmt(r.median, r.index === "kurtosis" || r.index === "worst" ? 1 : 2)}</td><td class="num">${fmt(r.low, 1)} to ${fmt(r.high, 1)}</td><td class="num">${fmt(r.sp500, r.index === "kurtosis" || r.index === "worst" ? 1 : 2)}</td></tr>`).join("")}</table>` };
const DRAW = {
  0: () => { seg("epsseg", Object.keys(X.kirman.eps), eps, v => { eps = v; DRAW[0](); }); const K = X.kirman.eps[eps], bb = base(), xs = [...Array(K.sim.length).keys()];
    document.getElementById("eps-tv").textContent = K.tv.toFixed(4);
    document.getElementById("eps-v").innerHTML = (K.tv < 0.05 ? '<span class="ok">passes</span>' : '<span style="color:var(--down)">does not pass</span>') +
      (+eps < X.kirman.threshold ? " · the ants herd" : " · the ants spread out");
    Plotly.newPlot("c_k", [{ x:xs, y:K.sim, type:"bar", marker:{color:P.herd, opacity:.5}, name:"Simulated" }, { x:xs, y:K.exact, mode:"lines", line:{color:P.real, width:2.5}, name:"Kirman's exact answer" }],
      base({ height:280, bargap:0, xaxis:{...bb.xaxis, title:{text:"Ants at source A"}}, yaxis:{...bb.yaxis, title:{text:"Share of time"}} }), CFG); },
  1: () => dots("c_1", X.checks.kurt, [-X.checks.bell.tol, X.checks.bell.tol], null, "Excess kurtosis", P.fund),
  2: () => dots("c_2", X.checks.tails, [2.5, 3.5], M.spx.tail, "Tail exponent", P.herd),
  3: () => { const R = X.checks.crash, bb = base();
    Plotly.newPlot("c_3", [{ x:R.map(r => r.size), y:R.map(r => r.bell), mode:"lines+markers", line:{color:P.bell, dash:"dot", width:2.5}, name:"Bell curve" },
      { x:R.filter(r => r.model !== null).map(r => r.size), y:R.filter(r => r.model !== null).map(r => r.model), mode:"lines+markers", line:{color:P.herd, width:2.5}, name:"Herding model" },
      { x:R.filter(r => r.sp500 !== null).map(r => r.size), y:R.filter(r => r.sp500 !== null).map(r => r.sp500), mode:"lines+markers", line:{color:P.real, width:2.5}, name:"S&P 500" }],
      base({ height:300, shapes:[{ type:"rect", xref:"paper", x0:0, x1:1, y0:0.1, y1:50, fillcolor:"rgba(52,211,153,.08)", line:{width:0}, layer:"below" }],
        xaxis:{...bb.xaxis, title:{text:"Size of the fall (typical days)"}}, yaxis:{...bb.yaxis, type:"log", range:[-1, 14], dtick:2, title:{text:"Years between such falls"}} }), CFG); } };
const ROWS = [["1. Kirman's ants", "Reproduce Kirman's ant model first", () => `Gap ${M.kirman.tv.toFixed(4)} (must be under 0.05)`, "ok", "✓ passes"],
  ["2. No trend chasers", "Returns follow a bell curve", () => `Excess kurtosis ${fmt(M.checks.kurt_median, 3)} (bell curve: 0)`, "ok", "✓ passes"],
  ["3. Fat tails", "Tail exponent about 2.6 to 3", () => `Model ${fmt(M.checks.tail_median)} · S&P 500 ${fmt(M.spx.tail)}`, "ok", "✓ passes"],
  ["4. Crashes", "Within decades, not 10⁸⁶ years", () => `8-typical-day falls every ${fmt(M.crash_years.model8, 0)} years; Black-Monday size every ${fmt(M.crash_years.bm_model, 0)}`, "mid", "≈ partly"],
  ["5. Extremes and bursts", "Comparable to the S&P 500", () => "Table inside", "", "no pass line"]];
function checks(v) {
  ct = v; seg("checktabs", CT, ct, checks);
  const box = document.getElementById("checkbox");
  if (v === CT[0]) {
    box.innerHTML = `<table><tr><th>CHECK</th><th>THE PROPOSAL SAID</th><th>RESULT</th><th>VERDICT</th></tr>${ROWS.map((r, i) =>
      `<tr class="checkrow ${openRow === i ? "open" : ""}" data-i="${i}"><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]()}</td><td class="${r[3]}">${r[4]}</td></tr>` +
      (openRow === i ? `<tr class="detail"><td colspan="4">${DETAIL[i]()}</td></tr>` : "")).join("")}</table>`;
    box.querySelectorAll(".checkrow").forEach(tr => tr.onclick = () => { openRow = openRow === +tr.dataset.i ? null : +tr.dataset.i; checks(ct); });
    if (openRow !== null && DRAW[openRow]) DRAW[openRow]();
  } else if (v === CT[1]) {
    const F = X.checks.facts, n = F[0].of;
    box.innerHTML = `<h3 class="eyebrow" style="margin:14px 0 6px">THE TEXTBOOK CHECKLIST (CONT, 2001), AGAINST A FORMULA WITH NO TRADERS</h3>
      <table><tr><th>PATTERN OF REAL MARKETS</th><th>S&amp;P 500</th><th>HERDING MODEL</th><th>FORMULA (GARCH)</th><th>RULE</th></tr>${F.map(f =>
      `<tr><td><b style="color:var(--text)">${f.name}</b><br><span class="cap">${f.meaning}</span></td><td>${f.sp500_pass ? "✅" : "❌"}</td>
       <td>${f.herding_pass > n / 2 ? "✅" : "❌"} ${f.herding_pass}/${n}</td><td>${f.garch_pass > n / 2 ? "✅" : "❌"} ${f.garch_pass}/${n}</td><td class="cap">${f.rule}</td></tr>`).join("")}</table>
      <h3 class="eyebrow" style="margin:22px 0 6px">DOES THE REBUILD GIVE THE PAPER'S NUMBERS? (LUX &amp; MARCHESI 1999)</h3>
      <table><tr><th>MEASURE</th><th class="num">PAPER</th><th class="num">OURS</th><th>VERDICT</th></tr>${X.paper.map(r =>
      `<tr><td>${r.measure}</td><td class="num">${fmt(r.paper)} ± ${fmt(r.paper_err, 3)}</td><td class="num">${fmt(r.ours)} ± ${fmt(r.ours_sd)}</td><td class="${r.close ? "ok" : ""}">${r.close ? "✓ close" : "✗ off"}</td></tr>`).join("")}</table>
      <h3 class="eyebrow" style="margin:22px 0 6px">EXTENSION · THE PRESIDENT'S PARTY</h3>
      <table><tr><th>MARKET</th><th>YEARS</th><th class="num">DEMOCRATS − REPUBLICANS, A YEAR</th><th class="num">BEATS LUCK IN</th></tr>${X.party.map(r => r.error ? `<tr><td>${r.name}</td><td colspan="3" class="cap">${r.error}</td></tr>` :
      `<tr><td>${r.name}</td><td>${r.years}</td><td class="num">${r.gap > 0 ? "+" : "−"}${fmt(Math.abs(r.gap) * 100, 1)} points</td><td class="num">${fmt(r.luck.gap ?? Object.values(r.luck)[0], 0)}% of shifted calendars</td></tr>`).join("")}</table>`;
  } else if (v === CT[2]) {
    const G = { Indexes:P.real, Stocks:"#7A8496", Commodities:"#E66A1F" };
    box.innerHTML = `<p class="cap" style="margin-top:0">Every saved market by its tail (across) and how much its wild days bunch up (up). The model was tuned on the S&amp;P 500 only.</p>
      <div class="mapchips">${Object.keys(G).map(g => `<button class="${mapGroups.has(g) ? "on" : ""}" data-g="${g}">${g}</button>`).join("")}</div><div class="chart" id="c_map"></div>`;
    box.querySelectorAll("[data-g]").forEach(b => b.onclick = () => { mapGroups.has(b.dataset.g) ? mapGroups.delete(b.dataset.g) : mapGroups.add(b.dataset.g); checks(ct); });
    const bb = base(), run = M.runs[String(M.fit_a1)];
    const tr = [...mapGroups].map(g => { const d = X.markets.filter(m => m.group === g);
      return { x:d.map(m => m.tail), y:d.map(m => m.memory), text:d.map(m => m.name), mode:"markers+text", textposition:"top center", textfont:{size:12, color:P.muted},
               marker:{size:10, color:G[g], symbol:g === "Stocks" ? "circle" : g === "Indexes" ? "square" : "diamond"}, name:g }; });
    tr.push({ x:[run.tail], y:[run.memory], mode:"markers+text", text:["Herding model"], textposition:"bottom center", textfont:{size:12, color:P.herd}, marker:{size:14, color:P.herd, symbol:"star"}, name:"Herding model" });
    Plotly.newPlot("c_map", tr, base({ height:460, shapes:[{ type:"rect", x0:2.5, x1:3.5, yref:"paper", y0:0, y1:1, fillcolor:"rgba(255,255,255,.04)", line:{width:0}, layer:"below" }],
      xaxis:{...bb.xaxis, title:{text:"Tail exponent (smaller = fatter tails)"}}, yaxis:{...bb.yaxis, title:{text:"Volatility memory (20 days)"}} }), CFG);
  } else {
    const secs = [...new Set(X.gallery.map(e => e.section))]; figSec = figSec || secs[0];
    box.innerHTML = `<div class="seg" id="figsec"></div><div class="gallery">${X.gallery.filter(e => e.section === figSec).map(e =>
      `<figure><img loading="lazy" src="figs/${e.file}" alt=""><figcaption>${e.caption.replace(" ✅", "")}</figcaption></figure>`).join("")}</div>`;
    seg("figsec", secs, figSec, s => { figSec = s; checks(ct); });
  }
}

